# install_app_from_parts.py
# Rebuilds the updated app.py from Base64 (gzip) parts, verifies SHA-256, backs up old app.py, and writes the new one.

import base64, gzip, hashlib, os, sys

APP = "app2.py"
BACKUP = "app.py.preinstall.bak"

# ---- Base64(GZIP(app.py)) split into 4 parts for easier copy/paste ----
PARTS = [
# --- PART 1/4 ---
r"""""",

# --- PART 2/4 ---
r"""""",

# --- PART 3/4 ---
r"""""",

# --- PART 4/4 ---
r"""""",
]

EXPECTED_SHA256 = "7da78fb29d12bc5c12f7c4c5b9d8146eb476a0b98f70f628a2e7a27d77f88875"

def main():
    b64 = "".join(PARTS).replace("\n","").strip()
    try:
        raw = gzip.decompress(base64.b64decode(b64))
    except Exception as e:
        print("❌ Failed to decode/decompress parts:", e)
        sys.exit(1)

    sha = hashlib.sha256(raw).hexdigest()
    if sha != EXPECTED_SHA256:
        print("❌ SHA-256 mismatch!")
        print("   Expected:", EXPECTED_SHA256)
        print("   Got     :", sha)
        print("   Aborting to protect your file.")
        sys.exit(2)

    # Backup existing app.py
    if os.path.exists(APP):
        with open(APP, "rb") as f:
            old = f.read()
        with open(BACKUP, "wb") as f:
            f.write(old)
        print(f"📦 Backed up existing {APP} -> {BACKUP}")

    with open(APP, "wb") as f:
        f.write(raw)

    line_count = raw.count(b"\n")
    print(f"✅ Wrote {APP} ({line_count} lines, {len(raw)} bytes)")
    print(f"🔐 SHA-256: {sha}")

if __name__ == "__main__":
    main()
